// Render the catalogue portraits as sprites; the source assets remain unchanged.
function sprite(img,key){const c=document.createElement('canvas');c.width=320;c.height=480;const g=c.getContext('2d');g.drawImage(img,0,0,320,480);const im=g.getImageData(0,0,320,480),d=im.data,seen=new Uint8Array(320*480),queue=new Int32Array(320*480);let head=0,tail=0;function add(p){if(seen[p])return;seen[p]=1;let k=p*4,r=d[k],v=d[k+1],b=d[k+2];if(key==='paster-fenrir'?(Math.max(r,v,b)-Math.min(r,v,b)<14&&r>90&&r<202):(Math.max(r,v,b)-Math.min(r,v,b)<23&&r>139&&r<235&&(key==='yaoi'?(v>=r+1&&b>=r+3):['gumon','kagachi','masa','deji'].includes(key)?(v>=r&&b>=r):true))){queue[tail++]=p;d[k+3]=0}}for(let x=0;x<320;x++){add(x);add(479*320+x)}for(let y=0;y<480;y++){add(y*320);add(y*320+319)}while(head<tail){let p=queue[head++],x=p%320;if(x)add(p-1);if(x<319)add(p+1);if(p>=320)add(p-320);if(p<479*320)add(p+320)}g.putImageData(im,0,0);return c}
