const sprites=[];let fenrirSprite=null;const fenrirImg=new Image();const fenrirReady=new Promise((resolve,reject)=>{fenrirImg.onload=()=>{fenrirSprite=sprite(fenrirImg,'paster-fenrir');resolve()};fenrirImg.onerror=reject;fenrirImg.src=window.ARENA_IMAGES['paster-fenrir']});Promise.all(imgs.map((im,i)=>new Promise((resolve,reject)=>{im.onload=()=>{sprites[i]=sprite(im,roster[i].key);resolve()};im.onerror=reject;im.src=window.ARENA_IMAGES[roster[i].key]||'assets/'+roster[i].key+'.webp'})).concat(fenrirReady,soldierReady)).then(()=>{loaded=true;reset()}).catch(()=>{$('message').textContent='画像を読み込めませんでした。ページを再読み込みしてください。';$('start').disabled=true});
