function renderMatchup(){selected.forEach((char,i)=>{const r=roster[char];colors[i]=selected[0]===selected[1]&&i===1?'#80dff5':r.color;$('portrait'+i).src=imgs[char].src;$('portrait'+i).alt=r.name;$('name'+i).innerHTML=r.name+' <em>'+(r.grade==null?'Grade —':'G'+r.grade)+'</em>';$('ability'+i).textContent=r.code;$('hp'+i).style.background=colors[i];$('select'+i).value=String(char);$('team'+i).innerHTML=skills[char].map((skill,j)=>'<div class="skill-slot" id="skill'+i+j+'"><span>'+skill.name+'</span><b>READY</b></div>').join('')+'<div class="skill-slot '+(r.overflow?'overflow-slot':r.key==='konke'?'poison-slot':r.key==='milk'?'regen-slot':r.key==='leorka'?'bomb-slot':r.key==='torie'?'reflect-slot':'passive-slot')+'" id="skill'+i+'3"><span>'+(r.overflow?'✦ オーバーフロウ':r.passiveLabel||'常時装甲 / OFなし')+'</span><b>'+(r.overflow?'HP'+Math.round((r.overflowRatio||OVERFLOW_RATIO)*100)+'%':r.key==='konke'?'毒0重':r.key==='milk'?'+12/s':r.key==='leorka'?'生成待機':r.key==='torie'?'30%':r.key==='masa'?'攻+0%':r.key==='zenomura'?'幻影0体':r.key==='deji'?'0重':'−38.5%')+'</b></div>'});canvas.setAttribute('aria-label',roster[selected[0]].name+'と'+roster[selected[1]].name+(manualMode?'の対戦フィールド（P1手動）':'の自動対戦フィールド'));$('fighter-info').innerHTML=selected.map((char,i)=>{const r=roster[char];return '<article><span class="dot" style="background:'+colors[i]+'"></span><div><h3>'+r.name+' <span>P'+(i+1)+'</span></h3><p>'+r.ability+'</p><dl>'+skills[char].map((skill,j)=>'<dt>0'+(j+1)+' '+skill.name+'</dt><dd>'+r.descs[j]+'</dd>').join('')+'<dt class="'+(r.overflow?'overflow-label':'armor-label')+'">'+(r.overflow?'04 オーバーフロウ：':r.passiveLabel?'戦闘特性：':'防御特性：')+r.overflowText+'</dt><dd>'+r.overflowDesc+'</dd></dl></div></article>'}).join('')}
