function drawMiniHole(s,collapse=0){const r=s.r*(collapse?1-collapse*.8:1),glow=ctx.createRadialGradient(0,0,r*.25,0,0,r*2.6);glow.addColorStop(0,'#030108');glow.addColorStop(.4,'#10051f');glow.addColorStop(.58,s.c+'cc');glow.addColorStop(1,s.c+'00');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,0,r*2.6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#050209';ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.strokeStyle=s.c;ctx.lineWidth=3;for(let n=0;n<3;n++){ctx.save();ctx.rotate(n*.9+(reduced?0:elapsed*3));ctx.beginPath();ctx.ellipse(0,0,r*(1.3+n*.25),r*.4,0,0,Math.PI*2);ctx.stroke();ctx.restore()}for(let n=0;n<9;n++){const a=n*2.4+(reduced?0:elapsed*2),d=r*(1.3+(n%3)*.45);ctx.fillStyle='#f5dcff';ctx.beginPath();ctx.arc(Math.cos(a)*d,Math.sin(a)*d,2,0,Math.PI*2);ctx.fill()}ctx.shadowBlur=0;ctx.fillStyle='#020105';ctx.beginPath();ctx.arc(0,0,r*.75,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e3b5ff';ctx.lineWidth=1.5;ctx.stroke()}

