function tickMudCannon(o){const f=fighters[o.owner],e=fighters[1-o.owner];if(!o.beamLocked){o.beamX=f.x;o.beamY=f.y-30;o.beamAngle=Math.atan2(e.y-f.y,e.x-f.x);if(o.t>=.7)o.beamLocked=true}if(o.t>=1&&!o.blast){o.blast=true;playSE('beam-fire',f)}while(o.pulses<7&&o.t>=1+o.pulses*.22&&running){o.pulses++;if(bloomBeamContact(o,e)){if(hit(e,o.pulses===7?110:65,f,'#c4a276',.5,false,'mud'))applyMudBind(e,.3);mudSplash(e.x,e.y,65)}}if(o.t>=o.duration||!running){overflow=null;$('skillcut').classList.remove('overflow');clearMotion()}}
