function rollXOverflow(){const roll=Math.random();return roll<.35?'freeze':roll<.7?'heat':'dual'}
function beginOverflow(id){const f=fighters[id];if(f.hp<=0||f.overflowUsed||!roster[f.char].overflow||f.petrified>0||isSilenced(f))return false;const kind=[0,20].includes(f.char)?'blackhole':f.char===3?'sculpture':f.char===4?'limit':f.char===9?'fortune':f.char===10?'repulsion':f.char===11?'sprout':f.char===12?'bloombeam':f.char===13?'unstoppable':f.char===14?'colossus':f.char===17?'randomizer':f.char===19?'thunderstorm':f.char===21?'frostrun':f.char===22?'mudcannon':f.char===23?'diamondmeteor':f.char===24?'stonefield':f.char===25?'riftmirror':rollXOverflow();const name=({blackhole:'ブラックホール',freeze:'空間冷凍',heat:'灼熱世界',dual:'双極',sculpture:'万象造形',limit:'限界チャージ',fortune:'絶対幸運・微笑みの絞首',repulsion:'全域反発空間',sprout:'芽生え',bloombeam:'絢爛爆華砲',unstoppable:'無敵の頂点',colossus:'圧倒的巨躯',randomizer:'ランダマイザ',thunderstorm:'天罰万雷',frostrun:'氷狼の大嵐',mudcannon:'泥砲・大地轟流',diamondmeteor:'ダイヤモンド・メテオ',stonefield:'沈黙の石庭',riftmirror:'転界反響・リターンゲート'})[kind],color=({blackhole:'#dbb2ff',freeze:'#a5f2ff',heat:'#ffb478',dual:'#edccff',sculpture:'#ffc1ed',limit:'#ffdf91',fortune:'#ffd0e3',repulsion:'#b0e5ff',sprout:'#c1efa2',bloombeam:'#ffd2e5',unstoppable:'#ffc28e',colossus:'#ffe1a8',randomizer:'#a8e8f5',thunderstorm:'#fff0a0',frostrun:'#c0f5ff',mudcannon:'#d4ad7d',diamondmeteor:'#e3e0ff',stonefield:'#d1d1af',riftmirror:'#b3c8ff'})[kind];fighters.forEach(releaseGrip);if(kind==='colossus')growKagachi(f);if(kind==='fortune')f.invincible=5.2;f.overflowUsed=true;f.overflowQueued=false;f.overflowName=name;f.windup=0;if(f.char===4)f.charge=1;f.dash=null;f.follow=0;fighters.forEach(v=>{v.dash=null;v.iceDash=null;v.follow=0;v.prevX=v.x;v.prevY=v.y;v.mx=0;v.my=0;v.vx=0;v.vy=0});overflow={owner:id,kind,name,color,duration:kind==='fortune'?4.5:['repulsion','thunderstorm','frostrun','stonefield','riftmirror'].includes(kind)?.8:kind==='sprout'?2.6:kind==='unstoppable'?.8:kind==='colossus'?4.1:3.1,t:0,pulses:0,blast:false,cx:W/2,cy:H/2+20,fromX:f.x,fromY:f.y};if(kind==='diamondmeteor')initDiamondMeteor(overflow);if(kind==='randomizer')overflow.effects=rollDisorders();if(kind==='bloombeam'||kind==='mudcannon')initBloomBeam(overflow);if(kind==='mudcannon')overflow.beamHalfWidth=105;cutin(f,name,color,true);$('skillcut').style.setProperty('--overflow-progress','1');$('skillcut').classList.add('overflow');$('cutname').textContent=roster[f.char].key.toUpperCase()+' / OVERFLOW';cutTimer=['repulsion','unstoppable','thunderstorm','frostrun','stonefield','riftmirror'].includes(kind)?1.3:overflow.duration+.05;playSE('of-'+kind,f);log('オーバーフロウ発動：残りHP'+Math.round(overflowRatio(f)*100)+'%以下・1戦に1回');return true}

function crowdOverflowTargets(owner){return [...diamondSoldiers.filter(v=>v.owner!==owner&&v.hp>0&&v.life>0),...fighters.filter(v=>v.id!==owner&&v.hp>0)]}
function tickCrowdOverflow(o,dt){
 const f=fighters[o.owner],thermal=['freeze','heat','dual'].includes(o.kind);
 if(o.t>.8){
  shots=[];
  if(['blackhole','sculpture'].includes(o.kind)){
   const pull=1-Math.exp(-(o.kind==='blackhole'?2.4:2)*dt);
   for(const target of crowdOverflowTargets(o.owner)){target.x+=(o.cx-target.x)*pull;target.y+=(o.cy-target.y)*pull;}
  }
  const thresholds=['heat','dual'].includes(o.kind)?[1.05,1.45,1.85]:[1.15,1.55,1.95];
  while(o.pulses<thresholds.length&&o.t>=thresholds[o.pulses]&&running){
   o.pulses++;
   for(const target of crowdOverflowTargets(o.owner)){
    if(!running)break;
    hit(target,({dual:93.6,heat:48,freeze:45.6,blackhole:44.2,sculpture:34})[o.kind],f,o.color,0,false,thermal?'thermal':'direct');
    burst(target.x,target.y-25,o.color,14);ring(target.x,target.y-25,o.color,20,['freeze','dual'].includes(o.kind)?'snow':'ring',.5);
    if(o.kind==='dual')ring(target.x,target.y-25,'#ffad75',15,'ring',.55);
   }
  }
  if(o.t>=2.4&&!o.blast){
   o.blast=true;
   for(const target of crowdOverflowTargets(o.owner)){
    if(!running)break;
    const landed=hit(target,({blackhole:338,freeze:324,heat:318,dual:642,sculpture:250})[o.kind],f,o.color,0,false,thermal?'thermal':'direct');
    ring(target.x,target.y-30,o.color,40,'impact',.8);burst(target.x,target.y-25,o.color,30);
    if(!landed||target.hp<=0)continue;
    if(['freeze','dual'].includes(o.kind))target.frozen=1.8;
    if(['heat','dual'].includes(o.kind)){target.burn=3.6;target.burnTick=.75;}
    if(o.kind==='sculpture'){target.bind=1.8;ring(target.x,target.y-30,o.color,80,'cage',1.1);}
    if(o.kind==='blackhole'){const angle=Math.atan2(target.y-f.y,target.x-f.x);target.x=clamp(target.x+Math.cos(angle)*135,55,W-55);target.y=clamp(target.y+Math.sin(angle)*135,135,H-65);target.turn=0;}
   }
   ring(o.cx,o.cy,o.color,20,'ring',.9);playSE('ultimate-impact',f);
  }
 }
 if(o.t>=o.duration||!running){overflow=null;$('skillcut').classList.remove('overflow');clearMotion();for(const v of diamondSoldiers){v.prevX=v.x;v.prevY=v.y;v.mx=v.my=0;}}
}

