  while(o.pulses<thresholds.length&&o.t>=thresholds[o.pulses]&&running){o.pulses++;hit(e,o.kind==='dual'?93.6:o.kind==='heat'?48:o.kind==='freeze'?45.6:o.kind==='blackhole'?44.2:34,f,o.color,0,false,['heat','freeze','dual'].includes(o.kind)?'thermal':'direct');burst(e.x,e.y-25,o.color,14);ring(e.x,e.y-25,o.color,20,o.kind==='freeze'?'snow':'ring',.5);if(o.kind==='dual'){ring(e.x,e.y-25,'#adf3ff',25,'snow',.55);ring(e.x,e.y-25,'#ffad75',15,'ring',.55)}}
